// th14_s5_b3: TH14 v1.00b Stage 5 boss non-spell 3.
// Source entry st05bs.ecl.txt::Boss2 (186-243); deps Boss2_at (245-286), Boss2_at2 (288-329).
// Entry anchor (0,144) = previous section's fixed move target; this entry's timerReset is T0.
// Shell: control carries the phase; the real boss carries source motion, boxes and firing.

const TIME_LIMIT: int = 2724;
const OPENING_BUFFER: int = 120;

// Native slot-0 interrupt: 2100 frames from timerReset -> BossCard2 (not included).
const NATIVE_LIMIT: int = 2100;

// Boss shared slots: int0 = moveRand step, int1 = segment clock; fx0/fx1 = drift unit vector.
const SLOT_CLK: int = 1;
const SLOT_DRIFT_K: int = 0;
const SLOT_DRIFT_COS: int = 0;
const SLOT_DRIFT_SIN: int = 1;

// Both emitters spawn type 15 (color 2 / 6), EX SETSPRITE swaps to type 8 and back.
// Source speeds: VELTIME 30->1.0, 50->3.0 (emitter 0) / 1.4 (emitter 1), 60->0.5.
xformdef RAMPS_A {
    @30 step_speed(1fx, 30);
    set_sprite(TH14_RICE, 2);
    @50 step_speed(3fx, 50);
    set_sprite(TH14_INVERT_RICE, 2);
    step_speed(0.5fx, 60);
}
xformdef RAMPS_B {
    @30 step_speed(1fx, 30);
    set_sprite(TH14_RICE, 6);
    @50 step_speed(1.4fx, 50);
    set_sprite(TH14_INVERT_RICE, 6);
    step_speed(0.5fx, 60);
}

sub adv(n: int) {
    wait(n);
    set_self_int(SLOT_CLK, self_int(SLOT_CLK) + n);
}

// st05bs.ecl.txt:245-286 Boss2_at -> emitter 0: fixed-direction ring, angle += F0 per shot.
sub boss2_at(ways: int, reps: int, f0: int) {
    sh_reset(0);
    sh_sprite(0, TH14_INVERT_RICE, 2);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, ways, 1);
    sh_speed(0, 2fx, 0fx);
    sh_xform(0, RAMPS_A);
    var a: int = rand(65536) - 32768;  // %A = %RANDRAD (BAM [-pi, pi))
    var b: int = 88;                   // etDist 96 - 4*2.0 ANIM birth offset
    var i: int = 0;
    while i < reps && self_int(SLOT_CLK) < NATIVE_LIMIT {
        sh_angle(0, a as angle, 0deg);  // loop resets source spread to 0
        sh_dist(0, b as fx);
        sh_fire(0);
        a = a + f0;
        b = b - 8;
        i = i + 1;
        adv(3);
    }
}

// st05bs.ecl.txt:288-329 Boss2_at2 -> emitter 1: same geometry, opposite F0*1.2 walk.
sub boss2_at2(ways: int, reps: int, f0: int) {
    sh_reset(1);
    sh_sprite(1, TH14_INVERT_RICE, 6);
    sh_aim(1, 0);
    sh_ring(1, 1);
    sh_count(1, ways, 1);
    sh_speed(1, 2fx, 0fx);
    sh_xform(1, RAMPS_B);
    var a: int = rand(65536) - 32768;
    var b: int = 88;
    var step: int = f0 * 6 / 5;        // %A -= %F0 * 1.2
    var i: int = 0;
    while i < reps && self_int(SLOT_CLK) < NATIVE_LIMIT {
        sh_angle(1, a as angle, 0deg);
        sh_dist(1, b as fx);
        sh_fire(1);
        a = a - step;
        b = b - 8;
        i = i + 1;
        adv(3);
    }
}

// moveRand(60,4,1.0) with moveLimit(0,128,280,96): speed 1*(1-k/60), rect x [-140,140], y [80,176].
sub arm_drift_step() {
    var k: int = self_int(SLOT_DRIFT_K) + 1;
    set_self_int(SLOT_DRIFT_K, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60fx; }
    var nx: fx = $self_x + self_fx(SLOT_DRIFT_COS) * speed;
    var ny: fx = $self_y + self_fx(SLOT_DRIFT_SIN) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub drift_begin() {
    var r: int = rand(65536) - 32768;  // signed unit random * pi, in BAM
    var a: int = 0;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05rad = 522 BAM.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(SLOT_DRIFT_COS, cos(a as angle));
    set_self_fx(SLOT_DRIFT_SIN, sin(a as angle));
    set_self_int(SLOT_DRIFT_K, 0);
    arm_drift_step();
}

sub drift_wait(n: int) {
    var i: int = 0;
    while i < n && self_int(SLOT_CLK) < NATIVE_LIMIT {
        wait(1);
        set_self_int(SLOT_CLK, self_int(SLOT_CLK) + 1);
        arm_drift_step();
        i = i + 1;
    }
}

async sub boss_body() {
    set_invuln(65535);                       // training shell (source setInvuln(120), no DPS here)
    set_hurtbox(24fx);                       // source setHurtbox(48,48): first value * 0.5
    set_hitbox(24fx);                        // source setHitbox(48,48): first value * 0.5
    set_self_int(SLOT_CLK, 0);               // source timerReset -> T0
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);  // source movePosTime(60,4,0,128) from (0,144)
    var f0: int = 419;                       // source %F0 = 0.040143rad
    var reps: int = 7;                       // source diffI($I0,7,10,12,12)
    var ways: int = 16;                      // source !E16 !N24 !H26 !LO30
    var rank: int = global(GVAR_RANK);
    if rank == RANK_NORMAL { reps = 10; ways = 24; }
    if rank == RANK_HARD { reps = 12; ways = 26; }
    if rank == RANK_LUNATIC { reps = 12; ways = 30; }
    adv(140);                                // source wait(140); moveLimit applied per frame in drift
    var drifting: int = 0;
    while self_int(SLOT_CLK) < NATIVE_LIMIT {
        if drifting == 0 { adv(60); } else { drift_wait(60); }
        if self_int(SLOT_CLK) >= NATIVE_LIMIT { break; }
        boss2_at(ways, reps, f0);
        boss2_at2(ways, reps, f0);
        adv(10);
        adv(60);
        f0 = 0 - f0;                         // source %F0 = %F0 * -1
        adv(60);
        drift_begin();                       // source moveRand(60,4,1.0)
        reps = reps + 1;                     // source $I0 = $I0 + 1
        drifting = 1;
    }
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 144fx, 13100, 0, 0, 0, boss_body);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// TH14 synthetic appearance aliases used by this card (see transcribe/th14/touhou-bullets.ecl).
// Native type N -> modern row: 0..23 same, 24..42 +1. Values are target row bases, not source types.
const TH14_RICE: int = 480;         // native type 8, base radius 2.4
const TH14_INVERT_RICE: int = 592;  // native type 15, base radius 2.4
